package com.thibaut.appel.data; import android.content.Context; import android.provider.CallLog; import android.provider.ContactsContract; data class Contact(val name:String,val number:String); fun loadContacts(c:Context):List<Contact>{val l=mutableListOf<Contact>();val cur=c.contentResolver.query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,null,null,null,null);cur?.use{val n=it.getColumnIndex(ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME);val u=it.getColumnIndex(ContactsContract.CommonDataKinds.Phone.NUMBER);while(it.moveToNext())l.add(Contact(it.getString(n)?:"",it.getString(u)?:""))};return l}
